    public static Color DeSerializeColorByHex(string target)
    {
        if (string.IsNullOrEmpty(target))
        {
            return default;
        }

        bool parseSuccess = ColorUtility.TryParseHtmlString(target, out Color color);
        if (parseSuccess)
        {
            return color;
        }
        return default;
    }

    public static float Normalization(this float value, float min, float max)
    {
        if (Mathf.Abs(max - min) < float.Epsilon)
        {
            LoggerUtils.LogError("Normalization Error:" + min + " " + max + " " + value);
            return value;
        }
        return (value - min) / (max - min);
    }

    public static float Normalization(this float value, float min, float max, float minRange, float maxRange)
    {
        if (Mathf.Abs(max - min) < float.Epsilon)
        {
            LoggerUtils.LogError("Normalization Error:" + min + " " + max + " " + value);
            return value;
        }
        return (value - min) / (max - min) * (maxRange - minRange) + minRange;
    }


    public static Vector2Int DeSerializeVector2Int(string target)
    {
        target = target.Trim('(', ')');
        string[] split = target.Split(',');
        int x = int.Parse(split[0], CultureInfo.InvariantCulture);
        int y = int.Parse(split[1], CultureInfo.InvariantCulture);
        return new Vector2Int(x, y);
    }

    public static Vector2 DeSerializeVector2(string target)
    {
        target = target.Trim('(', ')');
        var split = target.Split(',');
        var x = float.Parse(split[0], CultureInfo.InvariantCulture);
        var y = float.Parse(split[1], CultureInfo.InvariantCulture);
        return new Vector2(CheckNaNFloat(x), CheckNaNFloat(y));
    }

    public static Vector3 DeSerializeVector3(string target) {
        target = target.Trim('(', ')');
        var split = target.Split(',');
        var x = float.Parse(split[0], CultureInfo.InvariantCulture);
        var y = float.Parse(split[1], CultureInfo.InvariantCulture);
        var z = float.Parse(split[2], CultureInfo.InvariantCulture);
        return new Vector3(CheckNaNFloat(x), CheckNaNFloat(y), CheckNaNFloat(z));
    }

    public static Color DeSerializeColor(string target)
    {
        bool parseSuccess = ColorUtility.TryParseHtmlString("#" + target, out Color color);
        if (parseSuccess)
        {
            return color;
        }
        return Color.white;
    }

    public static Color DeSerializeColorCheckHash(string target)
    {
        if (string.IsNullOrEmpty(target)) return default;
        if (target.StartsWith('#'))
        {
            return DeSerializeColorByHex(target);
        }
        else
        {
            return DeSerializeColor(target);
        }
    }


    public static string ReplaceEmojiForSTM(string content)
    {
        MatchCollection emojiMatch = Regex.Matches(content, EmojiRegular1);
        foreach (Match e in emojiMatch)
        {
            string processedName = EmojiToBytes(e.Value);
            content = content.Replace(e.Value, "<q=" + processedName + ">");
        }
        emojiMatch = Regex.Matches(content, EmojiRegular2);
        foreach (Match e in emojiMatch)
        {
            string processedName = EmojiToBytes(e.Value);
            content = content.Replace(e.Value, "<q=" + processedName + ">");
        }
        return content;
    }

    public static string FilterNonStandardText(string content, string defCont = "")
    {
        string str = content;
        List<string> patten = new List<string>();
        patten.Add(@"\p{Cs}");
        patten.Add(@"\p{Co}");
        patten.Add(@"\p{Cn}");
        patten.Add(@"[\u2070-\u24ff]");
        patten.Add(@"[\u2580-\u2bff]");
        patten.Add(@"[\ud800-\uf8ff]");
        patten.Add(@"[\ufff0-\uffff]");
        for (int i = 0; i < patten.Count; i++)
        {
            str = Regex.Replace(str, patten[i], defCont);
        }
        return str;
    }

    public static string GetTextWithEmoji(string text, int limit = -1)
    {
        string targetStr = string.IsNullOrEmpty(text) ? "" : text;
        targetStr = limit > 0 ? GameUtils.SubStringByBytes(targetStr, limit) : targetStr;
        targetStr = ReplaceEmojiForSTM(targetStr);
        targetStr = FilterNonStandardText(targetStr);
        //targetStr = DataUtils.ReplaceRichText(targetStr);
        return targetStr;
    }

    public static string EmojiToBytes(string x)
    {
        var enc = new UTF32Encoding(true, false);
        var bytes = enc.GetBytes(x);

        var o = BitConverter.ToString(bytes);

        StringBuilder sb = new StringBuilder();

        bool odd = true;
        for (var i = 0; i < o.Length; i++)
        {
            var item = o[i];
            if (item == '-')
            {
                if (!odd)
                {
                    sb.Append(item);
                }
                odd = !odd;
            }
            else
            {
                sb.Append(item);
            }
        }
        sb = sb.Replace("0000-", string.Empty);
        sb = sb.Replace("0001-", "1");
        sb = sb.Replace("000E-", "E");

        return sb.ToString().ToLower();
    }

    // 过滤富文本和大部分Emoji
    public static string RemoveRichTextAndEmoji(string input)
    {
        string plainText = Regex.Replace(input, @"<[^>]*>|[\uD83C-\uDBFF\uDC00-\uDFFF\u2600-\u26FF\u2700-\u27BF]", string.Empty);
        return plainText;
    }
    
    public static string ReplaceRichText(string content)
    {
        return Regex.Replace(content, @"(<size|</size>|<color|</color>|<b>|</b>|<material|</material>|<quad>|</quad>)", "", RegexOptions.IgnoreCase);
    }

    /// <summary>
    /// 计算生成包围盒
    /// </summary>
    /// <param name="box"></param>
    /// <param name="isReset"></param>
    /// <returns></returns>
    public static Bounds CalculateBoundingBox(Transform box, bool isReset = false)
    {
        Vector3 postion = box.position;
        Quaternion rotation = box.rotation;
        if (isReset)
        {
            box.position = Vector3.zero;
            box.rotation = Quaternion.Euler(Vector3.zero);
        }

        Vector3 center = Vector3.zero;
        Renderer[] renders = box.GetComponentsInChildren<Renderer>(true);
        foreach (Renderer child in renders)
        {
            center += child.bounds.center;
        }
        if (renders.Length != 0) center /= renders.Length;
        Bounds bounds = new Bounds(center, Vector3.zero);
        foreach (Renderer child in renders)
        {
            bounds.Encapsulate(child.bounds);
        }
        if (isReset)
        {
            box.position = postion;
            box.rotation = rotation;
        }

        return bounds;
    }

    public static float CheckNaNFloat(float fValue)
    {
        if (float.IsNaN(fValue))
        {
            return 0;
        }
        return fValue;
    }


    public static string GetTimeStrByStampFormat(double stamp, string format = "HH:mm:ss:fff")
    {
        System.DateTime startTime = TimeZone.CurrentTimeZone.ToLocalTime(new System.DateTime(1970, 1, 1)); //当地时区
        var dt = startTime.AddMilliseconds(stamp);
        return dt.ToString(format, CultureInfo.InvariantCulture);
    }

    public static List<T> SaveGetRange<T>(List<T> list, int from, int to)
    {
        if (list == null || list.Count <= 0) return new List<T>();
        if (from > to) return new List<T>();
        if(from >= list.Count) return new List<T>();

        int fromCl = Mathf.Clamp(from, 0, list.Count - 1);
        int toCl = Mathf.Clamp(to, 0, list.Count);
        return list.GetRange(fromCl, toCl);
    }


    /// <summary>
    /// 倒计时时间 数字展示格式
    /// 1、超过一天的，显示为：x天xx小时
    /// 2、小于一天的，显示为：xx小时xx分钟
    /// </summary>
    /// <param name="timeStamp"></param>
    /// <returns></returns>
    public static string ToCountdownTimeString(long timeStamp) {
        DateTime sendTime = GameUtils.GetDataTimeStamp(timeStamp);
        TimeSpan span = sendTime - DateTime.Now;
        if (span.TotalDays >= 1d)
        {
            int days = (int)Math.Floor(span.TotalDays);
            string result = LocalizationManager.Inst.GetLocalizedText("{0}天{1}小时", days, span.Hours);
            return result;
        } else {
            int hours = (int)Math.Floor(span.TotalHours);
            string result = LocalizationManager.Inst.GetLocalizedText("{0}小时{1}分钟", hours, span.Minutes);
            return result;
        }
    }

    public static string ToLocalCountDownTime(long endTime)
    {
        string result = "";
        long remaining = endTime - GetUtcTimeStamp();
        remaining = Mathf.Max(1, (int)remaining);
        long day = remaining / 24 / 3600;
        long hour = (remaining / 3600 - 24 * day);
        if (day == 0 && hour == 0)
        {
            hour = 1;
        }
        
        if (day == 0)
        {
            result = LocalizationManager.Inst.GetLocalizedText("{0}小时", hour);
        }
        else
        {
            if (hour == 0)
            {
                result = LocalizationManager.Inst.GetLocalizedText("{0}天",day);
            }
            else
            {
                result = LocalizationManager.Inst.GetLocalizedText("{0}天{1}小时",day,hour);
            }
        }

        return result;
    }


    //  - 发布时间 数字展示形式
    //    1. 距离发布时间<1分钟：1 second ago、59 seconds ago
    //    2. 距离发布时间>=1分钟，<1小时：1 minute ago、59 minutes ago
    //    3. 距离发布时间>=1小时，<24小时：1 hour ago、23 hours ago
    //    4. 距离发布时间>=24小时(1天)，<7天：1 day ago、6 days ago
    //    5. 距离发布时间=7天，1 week ago
    //    6. 距离发布时间>7天，且为当前年份：February 17(月份全拼+空格+日期数字)
    //    7. 发布时间非当前年份：February 17, 2019(月份全拼+空格+日期数字+英文逗号+年份)
    public static string ToPublishTimeString(long timeStamp)
    {
        DateTime sendTime = GameUtils.GetDataTimeStamp(timeStamp);
        TimeSpan span = DateTime.Now - sendTime;
        if (span.TotalMinutes < 1d)
        {
            int seconds = (int)Math.Floor(span.TotalSeconds);
            string result = LocalizationManager.Inst.GetLocalizedText("{0}秒前", seconds);
            return result;
        }
        if (span.TotalHours < 1d)
        {
            int minutes = (int)Math.Floor(span.TotalMinutes);
            string result = LocalizationManager.Inst.GetLocalizedText("{0}分钟前", minutes);
            return result;

        }
        if (span.TotalDays < 1d)
        {
            int hours = (int)Math.Floor(span.TotalHours);
            string result = LocalizationManager.Inst.GetLocalizedText("{0}小时前", hours);
            return result;

        }
        if (span.TotalDays < 7d)
        {
            int days = (int)Math.Floor(span.TotalDays);
            string result = LocalizationManager.Inst.GetLocalizedText("{0}天前", days);
            return result;

        }
        if ((int)Math.Floor(span.TotalDays) == 7)
        {
            string result = LocalizationManager.Inst.GetLocalizedText("1周前");
            return result;
        }

        string defaultFromat = "yyyy年MM月dd日";
        #if PACKAGE_TYPE_US
        defaultFromat = "yyyy-MM-dd";
        #endif
        return sendTime.ToString(defaultFromat);

    }


    /// <summary>
    /// 当前时间是否在指定的时间戳范围内,
    /// </summary>
    /// <param name="start"></param>
    /// <param name="end"></param>
    /// <returns></returns>
    public static bool IsInRangeTimeStamp(long start, long end)
    {
        if (start >= end)
        {
            LoggerUtils.LogError("[DataUtil] start must less than end");
            return false;
        }

        var current = GetUtcTimeStamp();
        // LoggerUtils.Log($"[TimeStamp] start: {start}, current: {current}, end: {end}");
        return (current >= start) && (current <= end);
    }

